const fs = require('fs');

function solve() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (data.length === 0) return;
    const n = parseInt(data[0]);
    const k = parseInt(data[1]);
    const l = parseInt(data[2]);
    const MOD = 998244353;

    const maxN = 2 * n;
    const fact = new Array(maxN + 1).fill(1);
    for (let i = 1; i <= maxN; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    const invFact = new Array(maxN + 1).fill(1);
    invFact[maxN] = modPow(fact[maxN], MOD - 2, MOD);
    for (let i = maxN; i > 0; i--) {
        invFact[i - 1] = (invFact[i] * i) % MOD;
    }

    function C(n, r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    const I = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        const num = fact[i] * fact[i] % MOD;
        const den = fact[2 * i + 1];
        I[i] = num * modPow(den, MOD - 2, MOD) % MOD;
    }

    let ans = 0;
    for (let i = k; i <= n; i++) {
        const c1 = C(n, i);
        const c2 = C(i - 1, k - 1);
        const sign = (i - k) % 2 === 0 ? 1 : MOD - 1;
        let term = c1 * c2 % MOD;
        term = term * sign % MOD;
        term = term * I[i] % MOD;
        ans = (ans + term) % MOD;
    }

    ans = ans * l % MOD;
    console.log(ans);
}

function modPow(a, e, mod) {
    let res = 1;
    a %= mod;
    while (e > 0) {
        if (e & 1) res = res * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return res;
}

solve();
